#!/usr/bin/env python3"""TK1971 Avaitor AI System - Auto Restart Script24/7 Uptime Guarantee with Auto-Restart"""import osimport sysimport timeimport loggingimport subprocessfrom datetime import datetime# Configure logginglogging.basicConfig(    level=logging.INFO,    format='%(asctime)s - %(name)s - %(levelname)s - %(message)s',    handlers=[        logging.FileHandler('logs/startup.log'),        logging.StreamHandler()    ])logger = logging.getLogger(__name__)class SystemManager:    """24/7 সিস্টেম ম্যানেজার"""        def __init__(self):        self.process = None        self.restart_count = 0        self.max_restarts = 10000        self.start_time = datetime.now()        self.script_path = "tk1971_live_system.py"            def check_dependencies(self):        """ডিপেন্ডেন্সি চেক করুন"""        logger.info("🔍 Checking dependencies...")                required = ["python3", "pip"]        missing = []                for cmd in required:            try:                subprocess.run([cmd, "--version"], capture_output=True, check=True)                logger.info(f"✅ {cmd} is available")            except:                missing.append(cmd)                logger.error(f"❌ {cmd} is missing")                if missing:            logger.error(f"Missing dependencies: {missing}")            return False                return True        def install_requirements(self):        """রিকোয়ারমেন্টস ইনস্টল করুন"""        try:            logger.info("📦 Installing requirements...")                        if os.path.exists("requirements.txt"):                subprocess.run([sys.executable, "-m", "pip", "install", "-r", "requirements.txt"],                              check=True)                logger.info("✅ Requirements installed")            else:                logger.warning("⚠️ requirements.txt not found")                        return True        except subprocess.CalledProcessError as e:            logger.error(f"❌ Failed to install requirements: {e}")            return False        def setup_environment(self):        """এনভায়রনমেন্ট সেটআপ করুন"""        logger.info("🔧 Setting up environment...")                # Create necessary directories        directories = ["logs", "models", "data", "screenshots"]        for directory in directories:            os.makedirs(directory, exist_ok=True)            logger.info(f"📁 Created: {directory}")                # Set environment variables if not set        env_vars = {            'TK1971_PHONE': '09638427727',            'TK1971_PASSWORD': 's2TnYT7jhSh',            'TELEGRAM_TOKEN': '8539278490:AAFyg0ZxejKkiU1xUzCOPzmuB7B6amcbrIM',            'TELEGRAM_CHANNEL': '@Avaitor_live_signal_channel'        }                for key, value in env_vars.items():            if key not in os.environ:                os.environ[key] = value                logger.info(f"🔧 Set {key} = {value[:10]}...")                return True        def start_system(self):        """সিস্টেম শুরু করুন"""        try:            logger.info(f"🚀 Starting system (Attempt #{self.restart_count + 1})...")                        self.process = subprocess.Popen(                [sys.executable, self.script_path],                stdout=subprocess.PIPE,                stderr=subprocess.STDOUT,                text=True,                bufsize=1,                universal_newlines=True            )                        # Monitor output            for line in iter(self.process.stdout.readline, ''):                timestamp = datetime.now().strftime("%H:%M:%S")                print(f"[{timestamp}] {line.strip()}")                                # Check for critical errors                if any(word in line.lower() for word in ["fatal", "critical", "unrecoverable"]):                    logger.error(f"Critical error detected: {line}")                    return False                        return True                    except Exception as e:            logger.error(f"Startup error: {e}")            return False        def run(self):        """মেইন রান লুপ"""        logger.info("=" * 60)        logger.info("🤖 TK1971 AVIATOR AI 24/7 SYSTEM MANAGER")        logger.info("🎯 TARGET: 100% UPTIME")        logger.info("⏰ START TIME: " + self.start_time.strftime("%Y-%m-%d %H:%M:%S"))        logger.info("=" * 60)                # Initial setup        self.setup_environment()        self.check_dependencies()        self.install_requirements()                # Main restart loop        while self.restart_count < self.max_restarts:            try:                self.restart_count += 1                                logger.info(f"\n🔄 Restart #{self.restart_count}")                logger.info(f"⏰ System uptime: {datetime.now() - self.start_time}")                                # Start the system                if not self.start_system():                    logger.warning("System failed to start properly")                                # Wait for process to exit                return_code = self.process.wait()                logger.info(f"System exited with code: {return_code}")                                # Calculate wait time (exponential backoff)                wait_time = min(300, 30 * (2 ** min(self.restart_count // 10, 4)))                logger.info(f"⏳ Waiting {wait_time} seconds before restart...")                                # Send restart notification (if Telegram is working)                try:                    import asyncio                    from telegram import Bot                    bot = Bot(token=os.getenv('TELEGRAM_TOKEN'))                    asyncio.run(bot.send_message(                        chat_id=os.getenv('TELEGRAM_CHANNEL'),                        text=f"🔄 *System Restarting*\n\nAttempt #{self.restart_count}\nWait: {wait_time}s\n\n#AutoRestart"                    ))                except:                    pass                                time.sleep(wait_time)                            except KeyboardInterrupt:                logger.info("\n🛑 Stopped by user")                if self.process:                    self.process.terminate()                break            except Exception as e:                logger.error(f"Manager error: {e}")                time.sleep(60)                logger.info(f"📊 Total restarts: {self.restart_count}")        logger.info(f"⏰ Total uptime: {datetime.now() - self.start_time}")        logger.info("👋 System manager stopped")if __name__ == "__main__":    manager = SystemManager()    manager.run()